(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-941":{scenario:{company:"Công ty Tư vấn Môi trường Hưng Thịnh",supervisor:{name:"Cao Đức Mạnh",role:{vi:"Chủ nhiệm lập báo cáo ĐTM",en:"EIA Report Project Director"}},ref_code:"DTM-0526",title:{vi:"Đúng đối tượng nhạy cảm. Đúng mô hình lan truyền. Đánh giá trung thực.",en:"Right receptor. Right propagation model. Honest assessment."},brief:{vi:"Bạn hoàn thiện chương dự báo tiếng ồn của báo cáo đánh giá tác động môi trường DTM-0526 cho dự án cầu đường đô thị. Máy đóng cọc (nguồn điểm) đo 101 dBA ở 10 m; Trường Tiểu học Bình Minh cách vị trí đóng cọc 160 m. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa phân loại khu vực của trường học và mức ồn dự báo tại trường (dBA, 1 chữ số thập phân), rồi lập báo cáo có căn cứ. Đây là tình huống đào tạo.",en:"You are finalizing the noise chapter of environmental impact assessment report DTM-0526 for an urban bridge and road project. The piling rig (a point source) measures 101 dBA at 10 m; Binh Minh Primary School is 160 m from the piling location. Compare the draft with the approved file, correct the school's zone class and the predicted noise level at the school (dBA, 1 decimal), then write an evidence-based report. This is a training scenario."},reference_title:{vi:"Hồ sơ khảo sát & dự báo tiếng ồn đã duyệt · DTM-0526",en:"Approved noise survey & prediction file · DTM-0526"},fields:[{id:"ZONE_CLASS",label:{vi:"Phân loại khu vực tại trường học",en:"Zone class at the school"},initial:"ZONE-NORMAL",expected:"ZONE-SPECIAL",choices:["ZONE-SPECIAL","ZONE-NORMAL","ZONE-INDUSTRIAL"],reference:"Phiếu khảo sát đối tượng nhạy cảm",hint:{vi:"Trường học, bệnh viện, thư viện, nhà trẻ là khu vực đặc biệt, cần bảo vệ nghiêm ngặt hơn khu dân cư thông thường.",en:"Schools, hospitals, libraries and nurseries are special zones needing stricter protection than ordinary residential areas."}},{id:"NOISE_DBA",label:{vi:"Mức ồn dự báo tại trường (dBA)",en:"Predicted noise at the school (dBA)"},initial:"89.0",expected:"76.9",reference:"Bảng tính lan truyền tiếng ồn",ref_value:{vi:"Nguồn điểm 101 dBA tại r1 = 10 m; trường học tại r2 = 160 m",en:"Point source 101 dBA at r1 = 10 m; school at r2 = 160 m"},hint:{vi:"Nguồn điểm suy giảm 6 dB mỗi lần gấp đôi khoảng cách; chỉ nguồn đường mới suy giảm 3 dB.",en:"A point source drops 6 dB per doubling of distance; only a line source drops 3 dB."}}],sop32:{vi:"Nguồn điểm, bỏ qua hấp thụ không khí và vật cản (mô phỏng): L2 = L1 - 20 x log10(r2 / r1); giới hạn mô phỏng ban ngày: khu vực đặc biệt 55 dBA, khu vực thông thường 70 dBA; làm tròn 1 chữ số thập phân.",en:"Point source, ignoring air absorption and barriers (training): L2 = L1 - 20 x log10(r2 / r1); training daytime limits: special zone 55 dBA, normal zone 70 dBA; round to 1 decimal place."},context:{label:"BÁO CÁO ĐTM / DTM-0526",metrics:[{label:{vi:"Mức ồn nguồn tại 10 m",en:"Source level at 10 m"},value:"101 dBA"},{label:{vi:"Khoảng cách tới trường",en:"Distance to school"},value:"160 m"},{label:{vi:"Giới hạn khu đặc biệt",en:"Special zone limit"},value:"55 dBA"}]},crisis:{vi:"Chủ đầu tư nhắn: “Bỏ trường học ra khỏi danh sách đối tượng nhạy cảm, ghi khu dân cư thông thường cho nhẹ. Hội đồng thẩm định họp tuần sau, không kịp làm biện pháp giảm ồn đâu.”",en:"The project owner texts: “Take the school off the sensitive receptor list and call it an ordinary residential area. The appraisal council meets next week and there is no time for noise mitigation.”"},options:{safe:{vi:"Giữ đúng phân loại khu vực đặc biệt và kết quả dự báo, báo Chủ nhiệm báo cáo; đề xuất tường chắn ồn, cọc khoan nhồi thay đóng cọc và không thi công trong giờ học.",en:"Keep the special zone class and the prediction, inform the EIA Project Director and propose noise barriers, bored piles instead of driven piles and no piling during school hours."},shortcut:{vi:"Đổi trường học thành khu dân cư thông thường để báo cáo trông đạt chuẩn và kịp hội đồng.",en:"Relabel the school as an ordinary residential area so the report looks compliant in time."},wait:{vi:"Gửi bản nháp như hiện tại và chờ hội đồng thẩm định tự phát hiện.",en:"Submit the draft as is and wait for the appraisal council to spot the problem."}},questions:{vi:["Vì sao trường học phải xếp ZONE-SPECIAL? Mức ồn dự báo vượt giới hạn mô phỏng bao nhiêu dB?","Trình bày cách tính lan truyền tiếng ồn từ nguồn điểm và trách nhiệm của đơn vị tư vấn nếu che giấu đối tượng nhạy cảm."],en:["Why must the school be classed ZONE-SPECIAL? By how many dB does the prediction exceed the training limit?","Explain your point-source propagation calculation and the consultant's liability for hiding a sensitive receptor."]},hints:{vi:["Rà danh sách đối tượng nhạy cảm trong bán kính ảnh hưởng và đối chiếu chức năng sử dụng của từng công trình.","Xác định loại nguồn trước, rồi áp đúng hệ số 20 log theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được bỏ đối tượng nhạy cảm hay sửa kết quả dự báo; phải đề xuất biện pháp giảm thiểu khả thi."],en:["Review the sensitive receptors within the impact radius and check each building's actual use.","Identify the source type first, then apply the 20 log factor in SOP 3.2.","Re-read SOP 4.2: never drop a receptor or alter a prediction; propose feasible mitigation instead."]}},learning:{summary:{vi:"Chuyên viên đánh giá tác động môi trường nhận dạng, dự báo và đánh giá tác động của dự án đầu tư tới không khí, nước, đất, tiếng ồn, hệ sinh thái và cộng đồng; đề xuất biện pháp giảm thiểu, chương trình giám sát và tổ chức tham vấn. Nghề đòi hỏi kiến thức đa ngành, kỹ năng mô hình hóa, am hiểu Luật Bảo vệ môi trường và sự trung thực khoa học trước áp lực của chủ đầu tư.",en:"An environmental impact assessment specialist identifies, predicts and evaluates a project's effects on air, water, soil, noise, ecosystems and communities, and proposes mitigation, monitoring programs and public consultation. The role needs multidisciplinary knowledge, modeling skills, command of the Environmental Protection Law and scientific honesty under pressure from developers."},responsibilities:{vi:["Sàng lọc, xác định phân nhóm dự án và thủ tục môi trường phải thực hiện theo quy định.","Khảo sát, lấy mẫu hiện trạng môi trường nền và lập danh sách đối tượng nhạy cảm.","Dự báo tác động bằng mô hình lan truyền khí, ồn, nước và đánh giá mức độ tác động.","Đề xuất biện pháp giảm thiểu, chương trình quản lý và giám sát môi trường.","Tổ chức tham vấn cộng đồng, hoàn thiện báo cáo và giải trình trước hội đồng thẩm định."],en:["Screen projects and determine their category and the required environmental procedure.","Survey and sample baseline conditions and list sensitive receptors.","Predict impacts with air, noise and water models and rate their significance.","Propose mitigation measures and environmental management and monitoring programs.","Run public consultation, finalize the report and defend it before the appraisal council."]},competencies:[{name:{vi:"Sàng lọc & xác định phạm vi",en:"Screening & scoping"},desc:{vi:"Xác định nhóm dự án, ranh giới không gian, thời gian và các tác động chính cần đánh giá.",en:"Determine the project category, spatial and time boundaries and the key impacts to assess."}},{name:{vi:"Khảo sát môi trường nền",en:"Baseline survey"},desc:{vi:"Thiết kế mạng lưới lấy mẫu đại diện và bảo đảm số liệu đo thực tế, truy xuất được.",en:"Design representative sampling and ensure measured data is real and traceable."}},{name:{vi:"Mô hình hóa & dự báo",en:"Modeling & prediction"},desc:{vi:"Chọn đúng mô hình lan truyền, giả định thận trọng và kiểm tra độ nhạy của kết quả.",en:"Choose the right propagation model, use conservative assumptions and test sensitivity."}},{name:{vi:"Tham vấn cộng đồng",en:"Public consultation"},desc:{vi:"Trình bày tác động dễ hiểu, ghi nhận đầy đủ ý kiến và giải trình bằng văn bản.",en:"Explain impacts clearly, record all feedback and respond in writing."}},{name:{vi:"Trung thực khoa học",en:"Scientific integrity"},desc:{vi:"Không bỏ sót tác động, không sửa số liệu theo ý chủ đầu tư và báo cáo áp lực lên cấp trên.",en:"Never omit impacts or bend data for the developer, and escalate any pressure."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14: phân nhóm dự án I, II, III, IV, đánh giá tác động môi trường và giấy phép môi trường.","Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT: tiêu chí, nội dung và mẫu báo cáo đánh giá tác động môi trường.","Quy chuẩn kỹ thuật quốc gia về tiếng ồn, độ rung, chất lượng không khí và nước mặt (phiên bản hiện hành).","Nguyên lý lan truyền: suy giảm tiếng ồn nguồn điểm, nguồn đường và mô hình phát tán khí dạng Gauss.","Bộ tiêu chuẩn hoạt động về môi trường và xã hội của IFC (Performance Standards) cho dự án vay vốn quốc tế."],en:["Law on Environmental Protection No. 72/2020/QH14: project categories I to IV, EIA and environmental permits.","Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT: EIA criteria, content and report templates.","National technical regulations on noise, vibration, ambient air and surface water quality (current editions).","Propagation principles: point and line source noise attenuation and Gaussian air dispersion models.","IFC Performance Standards on environmental and social sustainability for internationally financed projects."]},tools:["Phần mềm GIS và bản đồ nền","Mô hình phát tán khí dạng Gauss","Phần mềm dự báo tiếng ồn giao thông, thi công","Máy đo ồn tích phân","Thiết bị lấy mẫu không khí, nước","Ma trận đánh giá tác động"],kpis:{vi:["Tỷ lệ báo cáo được hội đồng thẩm định thông qua mà không phải lập lại.","Độ sai lệch giữa dự báo và kết quả quan trắc khi dự án triển khai.","Tỷ lệ ý kiến tham vấn được tiếp thu, giải trình đầy đủ.","Số lần bị phát hiện thiếu đối tượng nhạy cảm hoặc số liệu không trung thực (mục tiêu bằng 0)."],en:["Share of reports approved by the appraisal council without resubmission.","Gap between predictions and monitoring results once the project runs.","Share of consultation comments addressed in full.","Cases of missing receptors or untruthful data found (target zero)."]},day:[{time:"08:00",vi:"Rà soát hồ sơ thiết kế cơ sở, quy mô, công nghệ và tiến độ thi công của dự án.",en:"Review the basic design, scale, technology and construction schedule."},{time:"09:30",vi:"Khảo sát hiện trường, đo ồn nền, lấy mẫu và lập bản đồ đối tượng nhạy cảm.",en:"Survey the site, measure background noise, take samples and map sensitive receptors."},{time:"13:30",vi:"Chạy mô hình dự báo ồn, bụi và lập ma trận đánh giá mức độ tác động.",en:"Run noise and dust models and build the impact significance matrix."},{time:"15:30",vi:"Họp tham vấn với chính quyền địa phương, nhà trường và người dân.",en:"Hold consultation with local authorities, the school and residents."},{time:"17:00",vi:"Viết chương biện pháp giảm thiểu và cập nhật nhật ký giả định mô hình.",en:"Draft the mitigation chapter and update the model assumptions log."}],mistakes:{vi:["Bỏ sót hoặc xếp sai đối tượng nhạy cảm như trường học, bệnh viện, nguồn nước sinh hoạt.","Dùng công thức suy giảm của nguồn đường cho nguồn điểm, làm dự báo sai lệch lớn.","Sao chép số liệu môi trường nền từ báo cáo khác thay vì khảo sát thực tế."],en:["Missing or misclassifying receptors such as schools, hospitals or drinking water sources.","Using line-source attenuation for a point source, badly skewing the prediction.","Copying baseline data from another report instead of surveying the site."]},career:[{vi:"Chuyên viên tư vấn môi trường",en:"Environmental consultant"},{vi:"Chuyên viên đánh giá tác động môi trường",en:"EIA specialist"},{vi:"Chủ nhiệm lập báo cáo ĐTM",en:"EIA project director"},{vi:"Giám đốc tư vấn môi trường & xã hội",en:"Environmental & social consulting director"}],glossary:[{term:"EIA",vi:"Đánh giá tác động môi trường: phân tích, dự báo tác động của dự án và đề xuất biện pháp giảm thiểu.",en:"Environmental impact assessment: analyzing and predicting a project's impacts and proposing mitigation."},{term:"Sensitive receptor",vi:"Đối tượng nhạy cảm: nơi có người hoặc hệ sinh thái dễ bị tác động như trường học, bệnh viện, khu bảo tồn.",en:"A place where people or ecosystems are easily affected, such as schools, hospitals or protected areas."},{term:"dBA",vi:"Mức áp suất âm có trọng số A, mô phỏng độ nhạy của tai người theo tần số.",en:"A-weighted sound pressure level reflecting the human ear's sensitivity to frequency."},{term:"Baseline",vi:"Hiện trạng môi trường nền: chất lượng môi trường trước khi dự án triển khai, dùng để so sánh tác động.",en:"Environmental conditions before the project, used as the reference for impacts."},{term:"Mitigation hierarchy",vi:"Thứ tự giảm thiểu: tránh, giảm thiểu, phục hồi rồi mới bù đắp phần tác động còn lại.",en:"Avoid, minimize, restore, and only then offset residual impacts."}],quiz:[{q:{vi:"Nguồn điểm 95 dBA tại 10 m. Bỏ qua hấp thụ không khí, mức ồn tại 40 m xấp xỉ bao nhiêu?",en:"A point source is 95 dBA at 10 m. Ignoring air absorption, what is the level at 40 m?"},options:{vi:["89 dBA","83 dBA","77 dBA","91 dBA"],en:["89 dBA","83 dBA","77 dBA","91 dBA"]},answer:1,explain:{vi:"L2 = 95 - 20 x log10(4) = 95 - 12 = 83 dBA; 89 dBA là kết quả sai khi dùng công thức nguồn đường.",en:"L2 = 95 - 20 x log10(4) = 95 - 12 = 83 dBA; 89 dBA wrongly uses the line-source formula."}},{q:{vi:"Đối tượng nào thường được xếp là khu vực đặc biệt khi đánh giá tiếng ồn?",en:"Which receptor is usually treated as a special zone in noise assessment?"},options:{vi:["Bãi đỗ xe","Kho hàng","Trường học, bệnh viện","Khu công nghiệp"],en:["Car park","Warehouse","School, hospital","Industrial park"]},answer:2,explain:{vi:"Trường học, bệnh viện, thư viện, nhà trẻ cần sự yên tĩnh nên áp dụng giới hạn ồn nghiêm ngặt hơn.",en:"Schools, hospitals, libraries and nurseries need quiet and face stricter noise limits."}},{q:{vi:"Chủ đầu tư đề nghị bỏ một bệnh viện khỏi danh sách đối tượng nhạy cảm cho kịp thẩm định. Bạn làm gì?",en:"The developer asks you to drop a hospital from the receptor list to meet the appraisal date. What do you do?"},options:{vi:["Giữ đúng đối tượng nhạy cảm, báo cấp trên và đề xuất biện pháp giảm thiểu khả thi","Bỏ đi vì chủ đầu tư chịu trách nhiệm","Ghi chú mờ trong phụ lục","Hoãn thẩm định vô thời hạn"],en:["Keep the receptor, escalate and propose feasible mitigation","Drop it since the developer is responsible","Bury a note in an annex","Postpone the appraisal indefinitely"]},answer:0,explain:{vi:"Đơn vị tư vấn chịu trách nhiệm về tính trung thực của số liệu; che giấu đối tượng nhạy cảm là vi phạm pháp luật và đạo đức nghề.",en:"The consultant is accountable for truthful data; hiding a receptor breaches the law and professional ethics."}},{q:{vi:"Theo thứ tự giảm thiểu tác động, biện pháp nào được ưu tiên đầu tiên?",en:"In the mitigation hierarchy, which step comes first?"},options:{vi:["Bù đắp","Phục hồi","Giảm thiểu","Tránh tác động"],en:["Offset","Restore","Minimize","Avoid"]},answer:3,explain:{vi:"Ưu tiên tránh tác động ngay từ thiết kế; bù đắp chỉ áp dụng cho tác động còn lại sau cùng.",en:"Avoidance at the design stage comes first; offsets apply only to the final residual impacts."}}],tools_en:["GIS software and base maps","Gaussian air dispersion model","Traffic & construction noise prediction software","Integrating sound level meter","Air and water sampling equipment","Impact assessment matrix"]}}})})(window.KKR);
